import{_ as i,C as s,o as t,c as n,a6 as a,b as l,w as r,a as d,E as c,a7 as u}from"./chunks/framework.4tsfTCyC.js";const w=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),h={name:"guide/index.md"};function p(g,e,m,f,b,y){const o=s("Mermaid");return t(),n("div",null,[e[1]||(e[1]=a('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>TeXRA is a multi-agent AI system for rigorous scientific work. Built as a VS Code extension, it orchestrates <strong>specialized agents</strong> — for literature search, manuscript drafting, figure generation, formal verification, symbolic computation, and result communication — and coordinates them through reproducible workflows where every output is auditable and every citation is grounded.</p><p><a href="https://marketplace.visualstudio.com/items?itemName=texra-ai.texra" target="_blank" style="display:inline-block;background-color:#007ACC;color:white;padding:10px 15px;text-decoration:none;border-radius:4px;font-weight:bold;margin:10px 0;">Install from VS Code Marketplace</a></p><h2 id="why-multi-agent" tabindex="-1">Why multi-agent? <a class="header-anchor" href="#why-multi-agent" aria-label="Permalink to &quot;Why multi-agent?&quot;">​</a></h2><p>The gap between having a result and having a correct, publishable manuscript is where most research time goes. A 40-page paper where notation must be consistent from Definition 2.1 through Appendix C. A bibliography where every entry is real and every <code>\\cite</code> key resolves. Commutative diagrams and Feynman diagrams that compile. A literature survey of a field where hundreds of papers appeared this year. A Lean formalization where the proof state needs careful tactic selection.</p><p>General-purpose AI tools make this worse, not better:</p><ul><li><strong>Hallucinated citations.</strong> Without grounded search tools, models fabricate references — dangerous in peer-reviewed work, unacceptable in mathematics.</li><li><strong>Lost structure.</strong> Chatbots can&#39;t reason across theorem environments, <code>\\label</code>/<code>\\ref</code> graphs, BibTeX databases, and multi-file projects simultaneously.</li><li><strong>No verification.</strong> You get text output with no way to compile, diff, type-check, or audit what changed.</li><li><strong>No tool access.</strong> A single prompt can&#39;t search Mathlib by type signature, run a WolframScript computation, compile TikZ, and verify the result.</li></ul><p>Scientific work needs a <em>system</em> of agents — each specialized, each grounded in real tools, each producing verifiable output.</p><h2 id="the-multi-agent-approach" tabindex="-1">The multi-agent approach <a class="header-anchor" href="#the-multi-agent-approach" aria-label="Permalink to &quot;The multi-agent approach&quot;">​</a></h2><p>TeXRA solves this with a team of agents that share context and use tools:</p>',10)),(t(),l(u,null,{default:r(()=>[c(o,{id:"mermaid-49",class:"mermaid",graph:"graph%20TB%0A%20%20%20%20User%5BUser%5D%20--%3E%20%7Cselects%20files%20%2B%20agent%7C%20Orchestrator%5BAgent%20Orchestrator%5D%0A%20%20%20%20Orchestrator%20--%3E%20WA%5BWorkflow%20Agents%5D%0A%20%20%20%20Orchestrator%20--%3E%20IA%5BInteractive%20Agents%5D%0A%0A%20%20%20%20WA%20--%3E%20%7Cpolish%2C%20correct%2C%20draw%7C%20Output%5BVersioned%20Output%20Files%5D%0A%20%20%20%20Output%20--%3E%20Diff%5BColor-Coded%20Diff%5D%0A%0A%20%20%20%20IA%20--%3E%20Tools%5BTool%20Access%5D%0A%20%20%20%20Tools%20--%3E%20Search%5BarXiv%20%2F%20Crossref%20%2F%20Zotero%5D%0A%20%20%20%20Tools%20--%3E%20Lean%5BLean%204%20%2F%20Loogle%20%2F%20Mathlib%5D%0A%20%20%20%20Tools%20--%3E%20Wolfram%5BWolframScript%5D%0A%20%20%20%20Tools%20--%3E%20Compile%5BLaTeX%20Compilation%5D%0A%20%20%20%20Tools%20--%3E%20FileOps%5BFile%20Operations%5D%0A%20%20%20%20Tools%20--%3E%20Shell%5BShell%20Commands%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h3 id="two-types-of-agents" tabindex="-1">Two types of agents <a class="header-anchor" href="#two-types-of-agents" aria-label="Permalink to &quot;Two types of agents&quot;">​</a></h3><p><strong>Workflow agents</strong> (<code>polish</code>, <code>correct</code>, <code>draw</code>, <code>paper2slide</code>, <code>paper2poster</code>) execute structured pipelines:</p><ol><li>Analyze your input files and instructions</li><li>Plan and execute changes via LLM calls</li><li>Optionally reflect on their output and iterate</li><li>Produce versioned output files (<code>*_r0_*</code>, <code>*_r1_*</code>) with diffs</li></ol><p><strong>Interactive agents</strong> (<code>chat</code>, <code>search</code>, <code>research</code>, <code>presenter</code>) operate conversationally with tool access:</p><ul><li>Read and edit files across your entire workspace</li><li>Search arXiv, Crossref, and Zotero for references with verified BibTeX</li><li>Search Mathlib by type signature (Loogle), inspect Lean proof states, check diagnostics</li><li>Run WolframScript for symbolic and numerical computation</li><li>Compile LaTeX and visually verify output</li><li>Maintain persistent context across multi-turn conversations</li></ul><h3 id="design-patterns" tabindex="-1">Design patterns <a class="header-anchor" href="#design-patterns" aria-label="Permalink to &quot;Design patterns&quot;">​</a></h3><p>The agent system is built on three established AI design patterns:</p><ol><li><strong>Reflection</strong> — agents examine their own output to identify errors and inconsistencies, running multiple rounds when rigor demands it</li><li><strong>Tool use</strong> — agents call external tools (compilers, Lean LSP, Loogle, WolframScript, search APIs, file systems) to ground their reasoning in verified data</li><li><strong>Planning</strong> — agents break complex tasks into steps, execute them sequentially, and adapt based on intermediate results</li></ol><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task</th><th>Agent</th><th>How it works</th></tr></thead><tbody><tr><td>Polish a manuscript</td><td><code>polish</code></td><td>Rewrites for clarity and precision, preserving all math environments and cross-references. Outputs a reviewable diff.</td></tr><tr><td>Fix LaTeX errors</td><td><code>correct</code></td><td>Finds and repairs compilation errors, notation inconsistencies, broken references, and formatting issues across multi-file projects.</td></tr><tr><td>Generate figures</td><td><code>draw</code></td><td>Creates TikZ diagrams — commutative diagrams, Feynman diagrams, phase portraits, lattice structures. Compiles and visually verifies every figure.</td></tr><tr><td>Search literature</td><td><code>search</code></td><td>Queries arXiv, Crossref, Zotero. Returns verified citations with BibTeX — no hallucinated references.</td></tr><tr><td>Work with Lean 4</td><td><code>research</code></td><td>Search Mathlib theorems via Loogle by type signature, inspect proof states, check diagnostics, manage builds and cache.</td></tr><tr><td>Symbolic computation</td><td><code>research</code></td><td>Run WolframScript to evaluate integrals, check identities, simplify expressions, or verify numerical results.</td></tr><tr><td>Build slide decks</td><td><code>presenter</code></td><td>Reads your paper, drafts a Beamer deck that preserves logical structure — definitions before theorems, diagrams in TikZ. Compiles and checks every page.</td></tr><tr><td>General research</td><td><code>research</code></td><td>Open-ended agent with full tool access for any research task.</td></tr><tr><td>Convert formats</td><td><code>paper2slide</code>, <code>paper2poster</code></td><td>Transform papers into presentations or posters.</td></tr></tbody></table><h2 id="who-uses-texra" tabindex="-1">Who uses TeXRA <a class="header-anchor" href="#who-uses-texra" aria-label="Permalink to &quot;Who uses TeXRA&quot;">​</a></h2><ul><li><strong>Mathematicians</strong> writing papers with complex theorem environments, maintaining notation consistency across long proofs, formalizing results in Lean 4</li><li><strong>Theoretical physicists</strong> managing multi-file manuscripts with extensive equation environments, Feynman diagrams, and large bibliographies</li><li><strong>Computational scientists</strong> producing papers that combine numerical methods, algorithm descriptions, convergence plots, and reproducible workflows</li><li><strong>PhD students</strong> maintaining consistency across thesis chapters, surveying literature in a new subfield, preparing seminar talks from written work</li><li><strong>Research groups</strong> collaborating on papers where every change needs to be traceable and auditable by co-authors and referees</li></ul><h2 id="privacy-and-data-handling" tabindex="-1">Privacy and data handling <a class="header-anchor" href="#privacy-and-data-handling" aria-label="Permalink to &quot;Privacy and data handling&quot;">​</a></h2><p>All API calls go <strong>directly from your machine</strong> to the model provider you choose (Anthropic, OpenAI, Google, etc.). TeXRA does not operate intermediate servers. Your unpublished proofs, manuscripts, and API keys never leave your machine except to the provider endpoint.</p><p>API keys are stored in VS Code&#39;s built-in Secret Storage.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/guide/installation.html">Installation</a> — set up TeXRA and its dependencies</li><li><a href="/guide/quick-start.html">Quick Start</a> — your first agent run in under five minutes</li><li><a href="/guide/built-in-agents.html">Built-in Agents</a> — the full catalog of available agents</li><li><a href="/guide/agent-architecture.html">Agent Architecture</a> — how the multi-agent system works under the hood</li><li><a href="/guide/custom-agents.html">Custom Agents</a> — build your own agents with YAML configuration</li></ul><p>If you spot a bug, email <a href="mailto:contact@texra.ai" target="_blank" rel="noreferrer">contact@texra.ai</a> or open an issue on <a href="https://github.com/texra-ai/texra-issues" target="_blank" rel="noreferrer">GitHub</a>.</p>',18))])}const A=i(h,[["render",p]]);export{w as __pageData,A as default};
